                "tags": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {"name": {"type": "string"}}
                    }
                }
            }
        });
        let out = to_strict_schema(&input);
        insta::assert_json_snapshot!(out);
    }
}

